function dist = dijkstra(n, adj, src)
% adj{u} = [v w; ...], 1-based index
    INF = 1e18;
    dist = INF * ones(n,1);
    dist(src) = 0;
    used = false(n,1);
    for it = 1:n
        u = -1;
        best = INF;
        for i=1:n
            if ~used(i) && dist(i) < best
                best = dist(i); u = i;
            end
        end
        if u == -1, break; end
        used(u) = true;
        edges = adj{u};
        for k = 1:size(edges,1)
            v = edges(k,1); w = edges(k,2);
            if dist(u) + w < dist(v)
                dist(v) = dist(u) + w;
            end
        end
    end
end

function total = kruskal_mst(n, edges)
% edges: [u v w] rows, 1-based indices
    edges = sortrows(edges, 3);
    p = (1:n)'; r = zeros(n,1);
    total = 0; cnt = 0;
    for i = 1:size(edges,1)
        u = edges(i,1); v = edges(i,2); w = edges(i,3);
        if dsu_unite(u, v)
            total = total + w; cnt = cnt + 1;
            if cnt == n-1, break; end
        end
    end
    if cnt ~= n-1, total = -1; end
    function x = dsu_find(x)
        while p(x) ~= x, p(x) = p(p(x)); x = p(x); end
    end
    function ok = dsu_unite(a,b)
        a = dsu_find(a); b = dsu_find(b);
        if a == b, ok = false; return; end
        if r(a) < r(b), t=a; a=b; b=t; end
        p(b) = a; if r(a) == r(b), r(a) = r(a)+1; end
        ok = true;
    end
end

function [dist, hasNeg] = bellman_ford(n, edges, src)
% edges: [u v w] 1-based
    INF = 1e18;
    dist = INF * ones(n,1); dist(src) = 0;
    for it = 1:n-1
        updated = false;
        for i = 1:size(edges,1)
            u = edges(i,1); v = edges(i,2); w = edges(i,3);
            if dist(u) < INF && dist(u) + w < dist(v)
                dist(v) = dist(u) + w; updated = true;
            end
        end
        if ~updated, break; end
    end
    hasNeg = false;
    for i = 1:size(edges,1)
        u = edges(i,1); v = edges(i,2); w = edges(i,3);
        if dist(u) < INF && dist(u) + w < dist(v)
            hasNeg = true; break;
        end
    end
end

function order = topo_sort_kahn(n, adj)
% adj{u} = [v1 v2 ...] row vector
    indeg = zeros(n,1);
    for u = 1:n, vs = adj{u}; indeg(vs) = indeg(vs) + 1; end
    q = find(indeg==0)';
    order = zeros(1,n); k = 0;
    head = 1;
    while head <= numel(q)
        u = q(head); head = head + 1;
        k = k + 1; order(k) = u;
        vs = adj{u};
        for i = 1:numel(vs)
            v = vs(i); indeg(v) = indeg(v) - 1;
            if indeg(v) == 0, q(end+1) = v; end %#ok<AGROW>
        end
    end
    order = order(1:k);
end

function idx = kmp_search(text, pat)
    n = length(text); m = length(pat);
    if m == 0, idx = []; return; end
    lps = zeros(1,m); i = 2; len = 0;
    while i <= m
        if pat(i) == pat(len+1)
            len = len + 1; lps(i) = len; i = i + 1;
        elseif len > 0
            len = lps(len);
        else
            lps(i) = 0; i = i + 1;
        end
    end
    idx = []; i = 1; j = 1;
    while i <= n
        if text(i) == pat(j)
            i = i + 1; j = j + 1;
            if j > m
                idx(end+1) = i - m; %#ok<AGROW>
                j = lps(j-1) + 1;
            end
        elseif j > 1
            j = lps(j-1) + 1;
        else
            i = i + 1;
        end
    end
end

function idx = rabin_karp(text, pat)
    n = length(text); m = length(pat);
    if m == 0 || m > n, idx = []; return; end
    B = 131; MOD = 1e9+7;
    powb = 1; for t = 1:m-1, powb = mod(powb * B, MOD); end
    hpat = 0; hwin = 0;
    for i = 1:m
        hpat = mod(hpat * B + double(pat(i)), MOD);
        hwin = mod(hwin * B + double(text(i)), MOD);
    end
    idx = [];
    for i = 0:n-m
        if hpat == hwin && strcmp(text(i+1:i+m), pat)
            idx(end+1) = i+1; %#ok<AGROW>
        end
        if i < n - m
            hwin = mod(hwin - double(text(i+1)) * powb, MOD);
            if hwin < 0, hwin = hwin + MOD; end
            hwin = mod(hwin * B + double(text(i+m+1)), MOD);
        end
    end
end

function is_prime = sieve_is_prime(n)
    % 返回大小为 n+1 的逻辑向量，is_prime(k) 表示整数 k 是否为素数
    is_prime = true(n+1,1);
    if n >= 1, is_prime(1) = false; end  % 1 不是素数
    p = 2;
    while p*p <= n
        if is_prime(p)
            x = p*p;
            while x <= n
                is_prime(x) = false;
                x = x + p;
            end
        end
        p = p + 1;
    end
end

function d = edit_distance(a, b)
    m = length(a); n = length(b);
    prev = 0:n; cur = zeros(1,n+1);
    for i = 1:m
        cur(1) = i; ai = a(i);
        for j = 1:n
            cost = (ai == b(j)); cost = 1 - cost;
            del = prev(j+1) + 1; ins = cur(j) + 1; rep = prev(j) + cost;
            cur(j+1) = min([del, ins, rep]);
        end
        tmp = prev; prev = cur; cur = tmp;
    end
    d = prev(n+1);
end

function L = lis_length(a)
    tails = [];
    for x = a(:)'
        l = 1; r = length(tails) + 1;
        while l < r
            m = floor((l + r)/2);
            if m <= length(tails) && tails(m) >= x
                r = m;
            else
                l = m + 1;
            end
        end
        if l > length(tails)
            tails(end+1) = x; %#ok<AGROW>
        else
            tails(l) = x;
        end
    end
    L = length(tails);
end

function val = quickselect(a, k) % k 1-based
    l = 1; r = numel(a); k = k - 1;
    while l <= r
        pivot = a(r); i = l;
        for j = l:r-1
            if a(j) <= pivot
                tmp = a(i); a(i) = a(j); a(j) = tmp; i = i + 1;
            end
        end
        tmp = a(i); a(i) = a(r); a(r) = tmp;
        if i-1 == k
            val = a(i); return;
        elseif i-1 > k
            r = i - 1;
        else
            l = i + 1;
        end
    end
    error('k out of range');
end

function [freq, magnitude] = fft_spectrum(signal, fs)
    N = length(signal);
    Y = fft(signal);
    magnitude = abs(Y(1:N/2+1));
    magnitude(2:end-1) = 2*magnitude(2:end-1);
    freq = (0:(N/2)) * fs / N;
end

