function [coeffs, r_squared] = linear_regression(x, y)
    x = x(:); y = y(:);
    X = [ones(length(x), 1), x];
    coeffs = X \ y;
    y_pred = X * coeffs;
    ss_res = sum((y - y_pred).^2);
    ss_tot = sum((y - mean(y)).^2);
    r_squared = 1 - (ss_res / ss_tot);
end

